import math

def is_perfect_cube(n):
    if n == 0:
        return True
    sign = 1 if n > 0 else -1
    abs_n = abs(n)
    root = round(abs_n**(1/3))
    return (root**3 == abs_n) and (sign * (root**3) == n)

def solve_d1():
    solutions = []
    # We check y in a reasonable range. Let's check up to |y| <= 15, while ensuring gcd(y, 65) = 1
    for y in range(-15, 16):
        if y == 0: continue
        if y % 5 == 0 or y % 13 == 0:
            continue # Ensures gcd(y, 65) = 1

        # Target equation: a^3 = 8y^3 - 65
        a_cubed = 8 * (y**3) - 65

        if is_perfect_cube(a_cubed):
            a = round(a_cubed**(1/3))
            if a**3 == a_cubed:
                # Found a solution (a, y)
                x = y**3 - 3

                # Double check the constraint: d = gcd(65, x+3) = gcd(65, y^3). 
                # Since we ensured gcd(y, 65) = 1, this condition is satisfied.

                solutions.append((x, a))

    return solutions

solutions = solve_d1()
print("Solutions found for the d=1 case (x, a):")
if solutions:
    for x, a in solutions:
        print(f"x = {x}, 8x-41 = {a**3}")
else:
    print("No solutions found for |y| <= 15.")

